def connect() -> sqlite3.Connection:
    connection = sqlite3.connect(DB_URI, uri=True, check_same_thread=False)
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA busy_timeout = 5000")
    return connection


_DATABASE_KEEPER = connect()


def _create_schema() -> None:
    with connect() as connection:
        connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS inventory (
                sku TEXT PRIMARY KEY,
                available_stock INTEGER NOT NULL CHECK (available_stock >= 0)
            );
            CREATE TABLE IF NOT EXISTS charges (
                id TEXT PRIMARY KEY,
                owner TEXT NOT NULL,
                status TEXT NOT NULL CHECK (status IN ('charged', 'refunded')),
                amount INTEGER NOT NULL CHECK (amount >= 0),
                currency TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS orders (
                id TEXT PRIMARY KEY,
                owner TEXT NOT NULL,
                status TEXT NOT NULL CHECK (status IN ('pending', 'canceled', 'completed')),
                line_items TEXT NOT NULL,
                charge_id TEXT NOT NULL UNIQUE REFERENCES charges(id),
                created_at TEXT NOT NULL,
                canceled_at TEXT
            );
            CREATE TABLE IF NOT EXISTS idempotency_records (
                owner TEXT NOT NULL,
                idempotency_key TEXT NOT NULL,
                request_fingerprint TEXT NOT NULL,
                order_id TEXT NOT NULL UNIQUE REFERENCES orders(id),
                PRIMARY KEY (owner, idempotency_key)
            );
            """
        )


