def _base64url_decode(value: str) -> bytes:
    return base64.b64decode(
        value + "=" * (-len(value) % 4), altchars=b"-_", validate=True
    )


def _verified_subject(token: str) -> str:
    try:
        header_segment, claims_segment, signature_segment = token.split(".")
        header = json.loads(_base64url_decode(header_segment))
        claims = json.loads(_base64url_decode(claims_segment))
        supplied_signature = _base64url_decode(signature_segment)
    except (ValueError, UnicodeDecodeError, json.JSONDecodeError, TypeError):
        raise HTTPException(status_code=401, detail="authentication required")

    if header != {"alg": "HS256", "typ": "JWT"} or not isinstance(claims, dict):
        raise HTTPException(status_code=401, detail="authentication required")
    signing_input = f"{header_segment}.{claims_segment}".encode("ascii")
    expected_signature = hmac.new(APP_SECRET, signing_input, hashlib.sha256).digest()
    if not hmac.compare_digest(supplied_signature, expected_signature):
        raise HTTPException(status_code=401, detail="authentication required")

    subject = claims.get("sub")
    if subject not in FIXTURE_SUBJECTS:
        raise HTTPException(status_code=401, detail="authentication required")
    return subject


bearer_scheme = HTTPBearer(
    auto_error=False,
    bearerFormat="JWT",
    scheme_name="bearerAuth",
)


def authenticate(
    credentials: Annotated[
        HTTPAuthorizationCredentials | None, Security(bearer_scheme)
    ],
) -> Principal:
    if credentials is None or credentials.scheme.lower() != "bearer":
        raise HTTPException(
            status_code=401,
            detail="authentication required",
            headers={"WWW-Authenticate": "Bearer"},
        )
    return Principal(subject=_verified_subject(credentials.credentials))


def _timestamp() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _order_from_row(connection: sqlite3.Connection, row: sqlite3.Row) -> dict:
    charge = connection.execute(
        "SELECT id, status, amount, currency FROM charges WHERE id = ?",
        (row["charge_id"],),
    ).fetchone()
    return {
        "id": row["id"],
        "customerId": row["owner"],
        "status": row["status"],
        "lineItems": json.loads(row["line_items"]),
        "charge": {
            "id": charge["id"],
            "status": charge["status"],
            "amount": charge["amount"],
            "currency": charge["currency"],
        },
        "createdAt": row["created_at"],
        "canceledAt": row["canceled_at"],
    }


def _read_order(connection: sqlite3.Connection, order_id: str) -> sqlite3.Row | None:
    return connection.execute(
        "SELECT * FROM orders WHERE id = ?", (order_id,)
    ).fetchone()


@app.get("/inventory/{sku}", response_model=InventoryItem)
def read_inventory(
    sku: str,
    principal: Annotated[Principal, Depends(authenticate)],
):
    with STATE_LOCK, connect() as connection:
        row = connection.execute(
            "SELECT sku, available_stock FROM inventory WHERE sku = ?", (sku,)
        ).fetchone()
    if row is None:
        raise HTTPException(status_code=404, detail="SKU not found")
    return {"sku": row["sku"], "stock": row["available_stock"]}


@app.post("/checkouts", response_model=CheckoutOrder, status_code=201)
def create_checkout(
    request: CheckoutCreateRequest,
    principal: Annotated[Principal, Depends(authenticate)],
    idempotency_key: Annotated[str | None, Header(alias="Idempotency-Key")] = None,
):
    if (
        not isinstance(idempotency_key, str)
        or not idempotency_key
        or len(idempotency_key) > MAX_IDEMPOTENCY_KEY_LENGTH
    ):
        raise HTTPException(status_code=400, detail="invalid Idempotency-Key")

    line_items = [item.model_dump() for item in request.lineItems]
    fingerprint = json.dumps(line_items, separators=(",", ":"), sort_keys=True)

    with STATE_LOCK, connect() as connection:
        connection.execute("BEGIN IMMEDIATE")
        prior = connection.execute(
            "SELECT request_fingerprint, order_id FROM idempotency_records "
            "WHERE owner = ? AND idempotency_key = ?",
            (principal.subject, idempotency_key),
        ).fetchone()
        if prior is not None:
            if prior["request_fingerprint"] != fingerprint:
                connection.rollback()
                raise HTTPException(
                    status_code=409, detail="idempotency request does not match"
                )
            row = _read_order(connection, prior["order_id"])
            order = _order_from_row(connection, row)
            connection.commit()
            return JSONResponse(status_code=200, content=order)

        required_by_sku: dict[str, int] = defaultdict(int)
        for item in line_items:
            required_by_sku[item["sku"]] += item["quantity"]

        for sku, required in required_by_sku.items():
            inventory = connection.execute(
                "SELECT available_stock FROM inventory WHERE sku = ?", (sku,)
            ).fetchone()
            if inventory is None or inventory["available_stock"] < required:
                connection.rollback()
                raise HTTPException(status_code=409, detail="insufficient stock")

        for sku, required in required_by_sku.items():
            connection.execute(
                "UPDATE inventory SET available_stock = available_stock - ? WHERE sku = ?",
                (required, sku),
            )

        order_id = str(uuid4())
        charge_id = str(uuid4())
        created_at = _timestamp()
        line_items_json = json.dumps(line_items, separators=(",", ":"))
        amount = sum(item["quantity"] * 100 for item in line_items)
        connection.execute(
            "INSERT INTO charges (id, owner, status, amount, currency) "
            "VALUES (?, ?, 'charged', ?, 'USD')",
            (charge_id, principal.subject, amount),
        )
        connection.execute(
            "INSERT INTO orders "
            "(id, owner, status, line_items, charge_id, created_at, canceled_at) "
            "VALUES (?, ?, 'pending', ?, ?, ?, NULL)",
            (order_id, principal.subject, line_items_json, charge_id, created_at),
        )
        connection.execute(
            "INSERT INTO idempotency_records "
            "(owner, idempotency_key, request_fingerprint, order_id) "
            "VALUES (?, ?, ?, ?)",
            (principal.subject, idempotency_key, fingerprint, order_id),
        )
        row = _read_order(connection, order_id)
        order = _order_from_row(connection, row)
        connection.commit()
    return order


@app.get("/checkouts", response_model=CheckoutListResponse)
def list_checkouts(principal: Annotated[Principal, Depends(authenticate)]):
    with STATE_LOCK, connect() as connection:
        rows = connection.execute(
            "SELECT * FROM orders ORDER BY created_at, id"
        ).fetchall()
        return {"orders": [_order_from_row(connection, row) for row in rows]}


@app.get("/checkouts/{orderId}", response_model=CheckoutOrder)
def read_checkout(
    orderId: str,
    principal: Annotated[Principal, Depends(authenticate)],
):
    with STATE_LOCK, connect() as connection:
        row = _read_order(connection, orderId)
        if row is None or row["owner"] != principal.subject:
            raise HTTPException(status_code=404, detail="checkout not found")
        return _order_from_row(connection, row)


@app.post("/checkouts/{orderId}/cancel", response_model=CheckoutOrder)
def cancel_checkout(
    orderId: str,
    principal: Annotated[Principal, Depends(authenticate)],
):
    with STATE_LOCK, connect() as connection:
        connection.execute("BEGIN IMMEDIATE")
        row = _read_order(connection, orderId)
        if row is None or row["owner"] != principal.subject:
            connection.rollback()
            raise HTTPException(status_code=404, detail="checkout not found")
        if row["status"] != "pending":
            order = _order_from_row(connection, row)
            connection.commit()
            return order

        for item in json.loads(row["line_items"]):
            connection.execute(
                "UPDATE inventory SET available_stock = available_stock + ? WHERE sku = ?",
                (item["quantity"], item["sku"]),
            )
        canceled_at = _timestamp()
        connection.execute(
            "UPDATE charges SET status = 'refunded' WHERE id = ? AND status = 'charged'",
            (row["charge_id"],),
        )
        connection.execute(
            "UPDATE orders SET status = 'canceled', canceled_at = ? WHERE id = ?",
            (canceled_at, orderId),
        )
        updated = _read_order(connection, orderId)
        order = _order_from_row(connection, updated)
        connection.commit()
    return order


